From 1af5f37f492992405219a674c4a9c3a13a503dab Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:15:30 +0100
Subject: [PATCH] shell: keep the clipboard manager running without the
 clipboard applet

Klipper only lived as long as a clipboard applet held it, so disabling
the Clipboard entry in the system tray also stopped clipboard history and
persistence. plasmashell now keeps its own reference to Klipper instead.

BUG: 423625
---
 shell/CMakeLists.txt           | 1 +
 shell/autotests/CMakeLists.txt | 1 +
 shell/shellcorona.cpp          | 3 +++
 shell/shellcorona.h            | 2 ++
 4 files changed, 7 insertions(+)

diff --git a/shell/CMakeLists.txt b/shell/CMakeLists.txt
index 05393e8838..0ac70f6298 100644
--- a/shell/CMakeLists.txt
+++ b/shell/CMakeLists.txt
@@ -133,6 +133,7 @@ target_link_libraries(plasmashell PRIVATE
  Plasma::Plasma
  Plasma::PlasmaQuick
  PW::KWorkspace
+ klipper
  Qt::GuiPrivate # qpa/qplatformwindow_p.h
  Qt::Quick
  Qt::DBus
diff --git a/shell/autotests/CMakeLists.txt b/shell/autotests/CMakeLists.txt
index 368cbd4542..af3c227471 100644
--- a/shell/autotests/CMakeLists.txt
+++ b/shell/autotests/CMakeLists.txt
@@ -59,6 +59,7 @@ MACRO(PLASMASHELL_UNIT_TESTS)
                             Wayland::Client
                             Wayland::Server
                             PW::KWorkspace
+                            klipper
                             LayerShellQt::Interface
                             SharedClientTest
                                      )
diff --git a/shell/shellcorona.cpp b/shell/shellcorona.cpp
index 51bde18ac6..a023e03ffa 100644
--- a/shell/shellcorona.cpp
+++ b/shell/shellcorona.cpp
@@ -61,6 +61,7 @@
 #include "futureutil.h"
 #include "kconfigloader.h"
 #include "kconfigpropertymap.h"
+#include "klipper.h"
 #include "osd.h"
 #include "panelview.h"
 #include "plasmashelladaptor.h"
@@ -165,6 +166,8 @@ void ShellCorona::init()
     QDBusConnection dbus = QDBusConnection::sessionBus();
     dbus.registerObject(QStringLiteral("/PlasmaShell"), this);

+    m_klipper = Klipper::self();
+
     // Look for theme config in plasmarc, if it isn't configured, take the theme from the
     // LookAndFeel package, if either is set, change the default theme

diff --git a/shell/shellcorona.h b/shell/shellcorona.h
index a85cd9aa07..ee99c97a8a 100644
--- a/shell/shellcorona.h
+++ b/shell/shellcorona.h
@@ -22,6 +22,7 @@
 #include <KPackage/Package>

 class DesktopView;
+class Klipper;
 class PanelView;
 class QMenu;
 class QScreen;
@@ -332,6 +333,7 @@ private:
     Plasma::Applet *m_showingAlternatives = nullptr;

     StrutManager *m_strutManager;
+    std::shared_ptr<Klipper> m_klipper;
     QPointer<ShellContainmentConfig> m_shellContainmentConfig;
     // The set of all the screens which have both the desktop and all panels (if any) fully loaded
     QSet<uint> m_screensWithUiReady;
